mapper.select:
SELECT d.id
FROM tui_dynamic d
WHERE d.status = 0
  AND d.id < #{cursor}
  AND EXISTS (
      SELECT 1
      FROM tui_follow f
      WHERE f.user_id = #{userId}
        AND f.status = 0
        AND f.follow_user_id = d.user_id
  )
ORDER BY d.id DESC
LIMIT #{limit}

SELECT recent.id
FROM (
    SELECT d.id, d.user_id
    FROM tui_dynamic d FORCE INDEX (idx_dynamic_status_id)
    WHERE d.status = 0
      AND d.id < #{cursor}
    ORDER BY d.id DESC
    LIMIT #{candidateLimit}
) recent
STRAIGHT_JOIN tui_follow f FORCE INDEX (idx_follow_covering)
  ON f.follow_user_id = recent.user_id
 AND f.user_id = #{userId}
 AND f.status = 0
ORDER BY recent.id DESC
LIMIT #{limit}

SELECT d.id, d.user_id, d.content, d.images, d.like_count, d.comment_count, d.share_count, d.create_time, d.update_time, d.status
FROM tui_dynamic d
INNER JOIN tui_follow f ON d.user_id = f.follow_user_id
WHERE f.user_id = #{userId} AND f.status = 0 AND d.status = 0 AND d.id < #{cursor}
ORDER BY d.id DESC
LIMIT #{limit}

SELECT id, user_id, content, images, like_count, comment_count, share_count, create_time, update_time, status
FROM tui_dynamic
WHERE user_id = #{userId} AND status = 0 AND id < #{cursor}
ORDER BY id DESC
LIMIT #{limit}

SELECT id FROM tui_dynamic
WHERE status = 0 AND create_time < #{beforeTime}
ORDER BY create_time ASC
LIMIT #{limit}
